SELECT COUNT(*)
FROM ANIME
WHERE 1=1

  AND anime_year = #{year}


  AND anime_quarter = #{quarter}

SELECT COUNT(*)
FROM ANIME
WHERE 1=1

  AND anime_year = #{year}


  AND anime_quarter = #{quarter}


  AND anime_title LIKE CONCAT('%', #{keyword}, '%')

SELECT COUNT(*)
FROM ANIME
WHERE 1=1

  AND anime_year = #{year}


  AND anime_quarter = #{quarter}


  AND INSTR(anime_story, #{keyword}) > 0

SELECT anime_id AS animeId, anime_title AS animeTitle, anime_year AS animeYear, anime_quarter AS animeQuarter, anime_thumbnail_url AS animeThumbnailUrl, anime_genres AS animeGenres FROM ANIME WHERE 1=1
AND anime_year = #{year}
AND anime_quarter = #{quarter}
ORDER BY anime_id ASC
ORDER BY anime_title ASC, anime_id DESC
ORDER BY anime_id DESC
LIMIT #{offset}, #{rows}

SELECT anime_id AS animeId, anime_title AS animeTitle, anime_year AS animeYear, anime_quarter AS animeQuarter, anime_thumbnail_url AS animeThumbnailUrl, anime_genres AS animeGenres FROM ANIME WHERE 1=1
AND anime_year = #{year}
AND anime_quarter = #{quarter}
AND anime_title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY anime_id ASC
ORDER BY anime_title ASC, anime_id DESC
ORDER BY anime_id DESC
LIMIT #{offset}, #{rows}

SELECT anime_id AS animeId, anime_title AS animeTitle, anime_year AS animeYear, anime_quarter AS animeQuarter, anime_thumbnail_url AS animeThumbnailUrl, anime_genres AS animeGenres FROM ANIME WHERE 1=1
AND anime_year = #{year}
AND anime_quarter = #{quarter}
AND INSTR(anime_story, #{keyword}) > 0
ORDER BY anime_id ASC
ORDER BY anime_title ASC, anime_id DESC
ORDER BY anime_id DESC
LIMIT #{offset}, #{rows}
